:root {
  --bg: #1a1c2c;
  --card: #f4f4f4;
  --ink: #1a1c2c;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --muted: #6b7280;
  --danger: #ef476f;
  --line: #1a1c2c;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%),
                    linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 4px solid var(--line);
  box-shadow: 8px 8px 0 var(--line);
  padding: 24px 20px;
}

.header { text-align: center; margin-bottom: 20px; }

h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.subtitle { margin: 4px 0 0; color: var(--muted); font-size: 0.95rem; }

.counts {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.count-box {
  flex: 1;
  border: 3px solid var(--line);
  padding: 10px;
  text-align: center;
  background: #fff;
}

.count-label {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.count-value {
  display: block;
  font-size: 1.6rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.add-row { display: flex; gap: 8px; margin-bottom: 20px; }

#todo-input {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  border: 3px solid var(--line);
  background: #fff;
  color: var(--ink);
}

#todo-input:focus-visible,
button:focus-visible,
input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--accent-dark);
  outline-offset: 2px;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  border: 3px solid var(--line);
  background: var(--accent);
  color: var(--ink);
  padding: 10px 16px;
  transition: transform 0.05s, box-shadow 0.05s;
  box-shadow: 3px 3px 0 var(--line);
}

button:hover { background: var(--accent-dark); }
button:active { transform: translate(3px, 3px); box-shadow: none; }

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 3px solid var(--line);
  background: #fff;
  padding: 8px 10px;
}

.todo-item input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent-dark);
  cursor: pointer;
  flex-shrink: 0;
}

.todo-text {
  flex: 1;
  overflow-wrap: anywhere;
  font-size: 1rem;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  color: var(--muted);
}

.todo-delete {
  padding: 6px 10px;
  font-size: 0.85rem;
  background: var(--danger);
  color: #fff;
  box-shadow: 2px 2px 0 var(--line);
}

.todo-delete:hover { background: #d63a5e; }

.empty-msg {
  text-align: center;
  color: var(--muted);
  margin: 12px 0 0;
  font-size: 0.95rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 20px 14px; }
  .add-row { flex-wrap: wrap; }
  #todo-input { flex-basis: 100%; }
  #todo-add { width: 100%; }
}

(function () {
  'use strict';

  var nextId = 1;
  var tasks = [];

  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var emptyMsg = document.getElementById('empty-msg');

  function updateCounts() {
    var remaining = 0;
    for (var i = 0; i < tasks.length; i++) {
      if (!tasks[i].done) remaining++;
    }
    totalEl.textContent = String(tasks.length);
    remainingEl.textContent = String(remaining);
    emptyMsg.hidden = tasks.length > 0;
  }

  function createTaskElement(task) {
    var li = document.createElement('li');
    li.className = 'todo-item';
    li.id = 'todo-item-' + task.id;

    var check = document.createElement('input');
    check.type = 'checkbox';
    check.id = 'todo-check-' + task.id;
    check.checked = task.done;
    check.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
    check.addEventListener('change', function () {
      task.done = check.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    var span = document.createElement('span');
    span.className = 'todo-text';
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'todo-delete';
    del.id = 'todo-delete-' + task.id;
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete task ' + task.id);
    del.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== task.id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(check);
    li.appendChild(span);
    li.appendChild(del);
    return li;
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) return;
    var task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    list.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    addTask();
  });

  // Ensure Enter key in the input triggers add (in case form submit is not fired)
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTask();
    }
  });

  updateCounts();
})();
